mapper.select:
SELECT * FROM ( SELECT T0.*, ROWNUM RNUM FROM (
SELECT A.QUSTNR_QESITM_ID AS QESTNR_QESITM_ID, A.QESTNR_ID, A.IEM_SN, A.QUSTNR_IEM_ID, A.IEM_CN, A.ETC_ANSWER_AT, A.QUSTNR_TMPLAT_ID AS QESTNR_TMPLAT_ID, A.FRST_REGIST_PNTTM AS FRST_REGISTER_PNTTM, A.FRST_REGISTER_ID, (SELECT USER_NM FROM COMVNUSERMASTER WHERE ESNTL_ID = A.FRST_REGISTER_ID) FRST_REGISTER_NM, A.LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID FROM COMTNQUSTNRIEM A WHERE 1=1
AND IEM_CN LIKE '%' || #{searchKeyword} || '%'
AND FRST_REGISTER_ID IN (SELECT ESNTL_ID FROM COMVNUSERMASTER WHERE USER_NM LIKE '%' || #{searchKeyword} || '%' )
ORDER BY A.FRST_REGIST_PNTTM DESC
) T0 ) WHERE RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}
